code.cpp:
class Solution {
public:
    int minimumMoves(string s) {
        int n = s.size();
        int count = 0;
        int i = 0;
        while (i < n) {
            if (s[i] == 'X') {
                count++;
                if (i <= n - 3) {
                    i += 3;
                } else {
                    break;
                }
            } else {
                i++;
            }
        }
        return count;
    }
};
